// One unique set of 49 semitones. Only the layout wraps on small displays.
const narrowPiano=matchMedia('(max-width: 650px)');
function pianoNoteName(midi){return roots.find(r=>r[1]===midi%12)[0]+(Math.floor(midi/12)-1)}
function continuousKeyRow(start,end,base,interactive){const white=m=>![1,3,6,8,10].includes(m%12),numbers=Array.from({length:end-start+1},(_,i)=>start+i),whiteCount=numbers.filter(white).length,padLeft=white(start)?0:.5,padRight=white(end)?0:.5,units=whiteCount+padLeft+padRight;let count=0;return `<div class="continuous-keyrow" style="--white-count:${whiteCount};--row-fraction:${units/15.5}">${numbers.map(m=>{const black=!white(m),pos=count;if(!black)count++;const offset=m-base,isC=m%12===0,name=pianoNoteName(m),style=black?`width:${62/units}%;left:${(padLeft+pos-.31)/units*100}%`:`position:absolute;top:0;left:${(padLeft+pos)/units*100}%;width:${100/units}%`;let hint='';if(interactive){if(offset>=0&&offset<keyHints.length)hint=keyHints[offset];else{const i=lowOffsets.indexOf(offset);if(i>=0&&i<7)hint=String(i+1)}}const attrs=interactive?`data-offset="${offset}" aria-label="${name}"`:`data-perf-midi="${m}"`;return `<${interactive?'button':'span'} class="${interactive?'live-key':'performance-key'} ${black?'black':'white'} ${isC?'octave-start':''}" ${attrs} style="${style}"><span>${name}</span>${interactive?`<kbd>${hint}</kbd>`:''}</${interactive?'button':'span'}>`}).join('')}</div>`}
function continuousKeyboard(start,base,interactive){const end=start+48;if(narrowPiano.matches){const split=start+23;return `<div class="continuous-segment"><div class="continuous-range">${pianoNoteName(start)} — ${pianoNoteName(split-1)} <small>由低到高 →</small></div>${continuousKeyRow(start,split-1,base,interactive)}</div><div class="continuous-segment"><div class="continuous-range">${pianoNoteName(split)} — ${pianoNoteName(end)} <small>接续上一排 →</small></div>${continuousKeyRow(split,end,base,interactive)}</div>`}return `<div class="octave-ranges four-octave-ranges"><span>左侧半八度</span><span>低音区</span><span>中音区</span><span>高音区</span><span>右侧半八度</span></div>${continuousKeyRow(start,end,base,interactive)}`}
// Numeric keys cover the lower octave; letter keys continue from middle C.
lowKeyboardCodes.splice(7);lowOffsets.splice(7);
pianoKeys=function(){const base=(octave+1)*12,start=typeof pianoReferenceStart==='function'?pianoReferenceStart(base):base-18;$('#liveKeyboard').innerHTML=continuousKeyboard(start,base,true);$('#octLabel').textContent=`${pianoNoteName(start)}–${pianoNoteName(start+48)}`;$('#pianoPanel .piano-toolbar small').textContent='中间三八度 + 两侧各半八度 · 49 键';liveVisual()};
$('#pianoPanel').classList.remove('two-registers');$('#pianoPanel').classList.add('continuous-piano-panel');$('#pianoPanel .piano-toolbar strong').textContent='四八度小钢琴';$('#pianoPanel .piano-help').innerHTML='<span>数字 1–7：低八度白键；字母 A S D F G H J K L ;：从中间 C 接着弹。</span><span>黑键 W E T Y U O P · Z / X 整体移八度 · 支持多指合奏</span>';
$('.backing-head span').textContent='按住按钮试听；也可在同一条键盘上自由合奏';
perfKeys=function(){const start=30+perfRoot()[1];$('#performanceKeys').innerHTML=`<div class="performance-unified"><div class="continuous-range">连续钢琴音区 · ${pianoNoteName(start)} — ${pianoNoteName(start+48)}</div>${continuousKeyboard(start,0,false)}</div>`;perfPaint()};
narrowPiano.addEventListener('change',()=>{releaseAll();pianoKeys();perfKeys();requestAnimationFrame(constrainDock)});pianoKeys();perfKeys();

$('#liveKeyboard').addEventListener('contextmenu',e=>e.preventDefault());$('#liveKeyboard').addEventListener('dragstart',e=>e.preventDefault());
